<?php namespace App\Notifications; use Illuminate\Bus\Queueable; use Illuminate\Notifications\Notification; class StatusReservasiNotification extends Notification { use Queueable; public $reservasi; public function __construct($reservasi) { $this->reservasi = $reservasi; } public function via($notifiable) { return ['database']; } public function toArray($notifiable) { $statusText = $this->reservasi->status == 'approved' ? 'disetujui' : ($this->reservasi->status == 'rejected' ? 'ditolak' : 'diperbarui'); return [ 'type' => 'reservasi', 'title' => 'Status Reservasi ' . ucfirst($statusText), 'message' => 'Pengajuan reservasi Anda telah ' . $statusText, 'url' => route('guest.riwayat') ]; } }